ruleToc.chapterList:
@js:
data=java.getString("@@a[title=Page]@text");
var page=data.match(/\/(\d+)/)[1];
var url=baseUrl.replace(/.html/,"_1.html")
var list=[{text:"第1页",href:baseUrl}];
if(data&&page){
	for(i=2;i<=page;i++){
		list.push({text:`第${i}页`,href:url.replace(/_1/,"_"+i)})
		}
		list;
	}

source.searchUrl:
@js:
(()=>{
  if(page==1){
    let url=source.getKey()+'/search/index.php,'+JSON.stringify({
  "body": `keyboard=${key}&show=title&tempid=2&tbname=article`,
  "charset": "GBK",
  "method": "POST"
});
    return java.put('surl',String(java.connect(url).raw().request().url()));
  } else {
    return java.get('surl')+'&page='+(page-1)
  }
})()

