source.bookSourceComment:
loginInfo = source.getLoginInfoMap();
loginInfo == null
  ? v = ""
  : v =
      loginInfo["Host"] == undefined || loginInfo["Host"] == ""
        ? ""
        : loginInfo["Host"];
host =
  v == 1
    ? "https://www.awslmh.net"
    : v == 2
    ? "https://www.abamh.com"
    : v == 3
    ? "https://abamh.com"
    : "https://www.awslmh.net"
headers = `{
  "v": ${v};
  "Host": ${host}
}`
source.putLoginHeader(headers);
function ti(text, i, z) {
  reg = new RegExp(i, "g");
  return text.replace(reg, z);
}
i = "姊姪唷徵";
z = "姐侄哟征";

